import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"賁","description":"周易集解 - 賁","frontmatter":{"title":"賁","description":"周易集解 - 賁"},"headers":[],"relativePath":"classics/jijie/022.md","filePath":"classics/jijie/022.md"}'),l={name:"classics/jijie/022.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="賁" tabindex="-1">賁 <a class="header-anchor" href="#賁" aria-label="Permalink to “賁”">​</a></h1><h2 id="賁-1" tabindex="-1">賁 <a class="header-anchor" href="#賁-1" aria-label="Permalink to “賁”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>賁，亨。小利有攸往。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：物不可以苟合而已，故受之以賁，賁者飾也。</p><p>崔憬曰：言物不可苟合於刑，當須以文飾之，故受之以賁。</p><p>虞翻曰：泰上之乾二，乾二之坤上，柔來文剛，陰陽交，故亨也。</p><p>虞翻曰：小謂五。五失正，動得位。體離，以剛文柔。故｢小利有攸往｣。</p><p>鄭玄曰：賁，文飾也。離為日，天文也。艮為石，地文也。天文在下，地文在上，天地二文，相飾成賁者也。猶人君以剛柔仁義之道飾成其德也。剛柔雜，仁義合，然後嘉會禮通，故亨也。卦互體坎艮，艮止於上，坎險於下，夾震在中，故不利大行，小有所之，則可矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：賁亨，柔來而文剛，故亨。分剛上而文柔，故小利有攸往。天文也。文明以止，人文也。觀乎天文，以察時變。觀乎人文，以化成天下。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>荀爽曰：此本泰卦。謂陰從上來，居乾之中，文飾剛道，交於中和，故亨也。分乾之二，居坤之上，上飾柔道，兼據二陰故小利有攸往矣。</p><p>虞翻曰：謂五。利變之正，成巽，體離。艮為星，離日坎月，巽為高。五天位。離為文明，日月星辰，高麗於上，故稱天之文也。</p><p>虞翻曰：人謂三。乾為人。文明，離。止，艮也。震動離明。五變據四，二五分則止文三，故以三為人文也。</p><p>虞翻曰：日月星辰為天文也。泰震春，兌秋。賁坎冬，離夏。巽為進退，日月星辰，進退盈縮，謂朓側朏也。曆象在天成變，故以察時變矣。</p><p>虞翻曰：泰乾為人。五二動，體既濟。賁離象，重明麗正，故以化成天下也。</p><p>乾寶曰：四時之變，縣乎日月；聖人之化，成乎文章。觀日月而要其會通，觀文明而化成天下。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：山下有火，賁。君子以明庶政，無敢折獄。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>王廙曰：山下有火，文相照也。夫山之為體，層峰峻嶺，峭嶮參差。直置其形，已如雕飾。復加火照，彌見文章。賁之象也。</p><p>虞翻曰：君子謂乾。離為明，坤為庶政，故明庶政。坎為獄，三在獄得正，故無敢折獄。噬嗑四不正，故利用獄也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九：賁其趾，舍車而徒。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：應在震，震為足，故賁其趾也。</p><p>虞翻曰：應在艮。艮為舍，坎為車；徒，步行也。位在下，故舍車而徒。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：舍車而徒，義弗乘也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：剛柔相交，以成飾義者也。今近四棄於二比，故曰舍車。車士大夫所乘，謂二也。四乘於剛，艮止其應，初全其義，故曰而徒。徒，塵賤之事也。自飾其行，故曰賁其趾。趾，謂初也。</p><p>王肅曰：在下，故稱趾。既舍其車，又飾其趾，是徒步也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二：賁其須。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：賁其須，與上興也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：自三至上，有頤之象也。二在頤下，須之象也。二無其應，三亦無應，若能上承於三，與之同德，雖俱無應，可相與而興起也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三：賁如濡如，永貞吉。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：永貞之吉，終莫之陵也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：有離之文以自飾。故曰賁如也。有坎之水以自潤，故曰濡如也。體剛履正，故永貞吉。與二同德，故終莫之陵也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四：賁如皤如，白馬翰如，匪寇婚媾。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>王弼曰：有應在初。三為寇難，二志相感，不獲交通。欲靜則失初之應，欲進則懼三之難，故或飾或素。內懷疑懼，鮮絜其馬，翰如以待。雖履正位，未果其志。匪緣寇隔，乃為婚媾，則終無尤也。</p><p>陸績曰：震為馬，為白，故曰白馬翰如。</p><p>案：皤亦白，素之貌也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六四，當位疑也。匪寇婚媾，終無尤也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>案：坎為盜，故疑。當位乘三，悖禮難飾，應初遠陽，故曰當位疑也。</p><p>崔憬曰：以其守正待應，故終無尤也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五：賁於丘園，束帛戔戔，吝。終吉。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：艮為山。五半山，故稱丘；木果曰園，故賁於丘園也。六五失正，動之成巽。巽為帛、為繩。艮手持，故束帛。以艮斷巽，故戔戔。失位無應，故吝。變而得正，故終吉矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六五之吉，有喜也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：艮，山。震，林。失其正位，在山林之間，賁飾丘陵，以為園圃，隱士之象也。五為王位，體中履和，勤賢之主，尊道之君也。故曰賁於丘園，束帛戔戔。君臣失正，故吝。能以中和飾上成功，故終吉而有喜也。</p><p>虞翻曰：五變之陽，故有喜。凡言喜慶，皆陽爻。束帛戔戔，委積之貌。</p><p>案：六五離爻，離為中女。午為蠶絲，束帛之象。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九：白賁，無咎。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：在巽上，故曰白賁。乘五，陰變而得位，故無咎矣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：白賁無咎，上得志也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>乾寶曰：白，素也。延山林之人，採素士之言，以飾其政，故上得志也。</p><p>虞翻曰：上之五得位，體成既濟，故曰得志。坎為志也。</p>',78)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
